    fun translate(text: String, language: String): String {
        val normalized = language.uppercase()
        if (normalized == "EN") return text
        // Translate a known interface prefix while leaving the user-provided source title intact.
        if (text.startsWith("Open source conversation · ")) {
            val title = text.removePrefix("Open source conversation · ")
            return if (normalized == "PL") "Otwórz rozmowę źródłową · $title" else if (normalized == "TR") "Kaynak sohbeti aç · $title" else text
        }
        if (text.startsWith("Open source · ")) {
            val title = text.removePrefix("Open source · ")
            return if (normalized == "PL") "Otwórz źródło · $title" else if (normalized == "TR") "Kaynağı aç · $title" else text
        }
        if (text.startsWith("Relationships (") && text.endsWith(")")) {
            return if (normalized == "PL") text.replaceFirst("Relationships", "Relacje") else if (normalized == "TR") text.replaceFirst("Relationships", "İlişkiler") else text
        }
        if (text.startsWith("Target: ")) {
            val suffix = text.removePrefix("Target: ")
            return if (normalized == "PL") "Cel: $suffix" else if (normalized == "TR") "Hedef: $suffix" else text
        }
        val metadataPrefixes = listOf(
            "Runtime · " to ("Środowisko · " to "Çalışma zamanı · "),
            "Capability · " to ("Funkcja · " to "Yetenek · "),
            "Expiry · " to ("Wygaśnięcie · " to "Son kullanma · "),
            "Evidence · " to ("Dowód · " to "Kanıt · ")
        )
        metadataPrefixes.firstOrNull { text.startsWith(it.first) }?.let { (prefix, labels) ->
            val suffix = text.removePrefix(prefix)
            return when (normalized) { "PL" -> labels.first + suffix; "TR" -> labels.second + suffix; else -> text }
        }
        val pair = translations[text] ?: return text
        return when (normalized) {
            "PL" -> pair.first
            "TR" -> pair.second
            else -> text
        }
    }
}

@Composable
fun MemoText(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    fontSize: TextUnit = TextUnit.Unspecified,
    fontStyle: FontStyle? = null,
    fontWeight: FontWeight? = null,
    fontFamily: FontFamily? = null,
    letterSpacing: TextUnit = TextUnit.Unspecified,
    textDecoration: TextDecoration? = null,
    textAlign: TextAlign? = null,
    lineHeight: TextUnit = TextUnit.Unspecified,
    overflow: TextOverflow = TextOverflow.Clip,
    softWrap: Boolean = true,
    maxLines: Int = Int.MAX_VALUE,
    minLines: Int = 1,
    onTextLayout: (TextLayoutResult) -> Unit = {},
    style: TextStyle = LocalTextStyle.current
) {
    val translated = MemoLocalization.translate(text, LocalMemoLanguage.current)
    Material3Text(
        text = translated,
        modifier = modifier,
        color = color,
        fontSize = fontSize,
        fontStyle = fontStyle,
        fontWeight = fontWeight,
        fontFamily = fontFamily,
        letterSpacing = letterSpacing,
        textDecoration = textDecoration,
        textAlign = textAlign,
        lineHeight = lineHeight,
        overflow = overflow,
        softWrap = softWrap,
        maxLines = maxLines,
        minLines = minLines,
        onTextLayout = onTextLayout,
        style = style
    )
}

